import React, { useEffect, useState } from 'react';
import axios from 'axios';
import './Profile.css';

const Profile = () => {
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const fetchProfile = async () => {
      try {
        const token = localStorage.getItem("token");
        const response = await axios.get("http://localhost:8082/api/profiles", {
          headers: { Authorization: `Bearer ${token}` },
        });
        setProfile(response.data);
      } catch (err) {
        setError("Failed to fetch profile");
      } finally {
        setLoading(false);
      }
    };

    fetchProfile();
  }, []);

  if (loading) return <p>Loading profile...</p>;
  if (error) return <p>{error}</p>;
  if (!profile) return <p>No profile data found.</p>;

  return (
    <div className="content-area">

      {/* HEADER SA TAAS – ICON LANG */}
      <div className="top-header-icon-only">
        <div className="header-avatar">👤</div>
      </div>

      {/* EXISTING PROFILE CARD */}
      <div className="profile-container">
        <div className="profile-header-card">
          <div className="avatar-circle">👤</div>
          <button className="edit-btn">🖊️ Edit Profile</button>
        </div>

        <div className="profile-details-card">
          <h2>{profile.firstName} {profile.lastName}</h2>

          <div className="details-box">
            <h3 className="box-title">Profile details</h3>

            <div className="details-grid">
              <div className="detail-item">
                <span className="icon">👤</span>
                <div>
                  <label>Full Name</label>
                  <p>{profile.firstName} {profile.lastName}</p>
                </div>
              </div>

              <div className="detail-item">
                <span className="icon">📞</span>
                <div>
                  <label>Number</label>
                  <p>{profile.number}</p>
                </div>
              </div>

              <div className="detail-item">
                <span className="icon">👤</span>
                <div>
                  <label>Username</label>
                  <p>{profile.username || profile.firstName}</p>
                </div>
              </div>

              <div className="detail-item">
                <span className="icon">📍</span>
                <div>
                  <label>Address</label>
                  <p>{profile.address}</p>
                </div>
              </div>

              <div className="detail-item">
                <span className="icon">📅</span>
                <div>
                  <label>Date of Birth</label>
                  <p>{profile.dob || "Not provided"}</p>
                </div>
              </div>
            </div>

          </div>
        </div>
      </div>

    </div>
  );
};

export default Profile;
